function getAudioContext(){audioContext??=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();return audioContext}
function playSound(kind='tap'){
 if(!audioEnabled)return;
 try{
  getAudioContext();
  const now=audioContext.currentTime,notes={tap:[440,.035,.035],reveal:[620,.07,.07],success:[660,.11,.16],lose:[180,.16,.12],spin:[260,.05,.05]}[kind]||[440,.04,.04];
  const oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.type=kind==='lose'?'sawtooth':'sine';oscillator.frequency.setValueAtTime(notes[0],now);if(kind==='success')oscillator.frequency.exponentialRampToValueAtTime(990,now+notes[1]);if(kind==='lose')oscillator.frequency.exponentialRampToValueAtTime(120,now+notes[1]);gain.gain.setValueAtTime(notes[2],now);gain.gain.exponentialRampToValueAtTime(.0001,now+notes[1]);oscillator.connect(gain).connect(audioContext.destination);oscillator.start(now);oscillator.stop(now+notes[1]);
 }catch{}
}
function selectedMusicTrack(){return musicCatalog.tracks.find(track=>track.id===musicTrackId)||musicCatalog.tracks.find(track=>track.id===musicCatalog.defaultTrackId)||musicCatalog.tracks[0]}
function scheduleMusic(){if(!musicEnabled||!musicGain||!audioContext)return;const track=selectedMusicTrack();if(!track)return;const preset=musicPresets[track.style]||musicPresets.ambient,now=audioContext.currentTime+0.05,chord=preset.chords[musicStep++%preset.chords.length];chord.forEach((frequency,index)=>{const oscillator=audioContext.createOscillator(),gain=audioContext.createGain(),start=now+index*preset.stagger;oscillator.type=preset.waves[index%preset.waves.length];oscillator.frequency.value=frequency*preset.octave;gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(preset.gain*(index?1:.12+1),start+preset.attack);gain.gain.exponentialRampToValueAtTime(.0001,now+preset.duration-.1);oscillator.connect(gain).connect(musicGain);oscillator.start(start);oscillator.stop(now+preset.duration)})}
function startMusic(){if(!musicEnabled||musicTimer||!selectedMusicTrack())return;try{getAudioContext();const preset=musicPresets[selectedMusicTrack().style]||musicPresets.ambient;musicGain=audioContext.createGain();musicGain.gain.value=.5;musicGain.connect(audioContext.destination);scheduleMusic();musicTimer=setInterval(scheduleMusic,preset.interval)}catch{}}
function stopMusic(){if(musicTimer)clearInterval(musicTimer);musicTimer=null;if(musicGain){const gain=musicGain;musicGain=null;try{gain.gain.cancelScheduledValues(audioContext.currentTime);gain.gain.setTargetAtTime(.0001,audioContext.currentTime,.08);setTimeout(()=>{try{gain.disconnect()}catch{}},500)}catch{try{gain.disconnect()}catch{}}}}
